const OWNER = 'prn_fbab9aa00cd46169';
const body = ($json && typeof $json.body === 'object' && $json.body) ? $json.body : {};
const now = new Date();
const explicit = typeof body.topic === 'string' && body.topic.trim().length >= 5;
const sourceCaseId = typeof body.source_case_id === 'string' ? body.source_case_id.trim() : '';
const rawActionId = typeof body.source_action_id === 'string' ? body.source_action_id.trim() : '';
if (rawActionId && !/^act_[a-f0-9]+$/.test(rawActionId)) throw new Error('Подготовить контекст запуска: source_action_id должен соответствовать ^act_[a-f0-9]+$');
const requestedActionId = /^act_[a-f0-9]+$/.test(rawActionId) ? rawActionId : '';
const scheduledFocus = ['atlas','radar','graph'][now.getUTCHours() % 3];
const proposedKey = explicit && typeof body.run_key === 'string' ? body.run_key : `curator-${now.toISOString().slice(0,13).replace(/[-T:]/g,'')}`;
const runKey = String(proposedKey).replace(/[^A-Za-z0-9_.:-]/g, '-').slice(0, 160);
return [{json: {
  owner: OWNER,
  run_key: runKey,
  trigger: explicit ? 'researcher' : 'schedule',
  requested_topic: explicit ? body.topic.trim().slice(0, 500) : `Плановый фокус ${scheduledFocus}: выбери одно незакрытое действие этого дела и продолжай машинно.`,
  source_case_id: sourceCaseId,
  requested_source_action_id: requestedActionId,
  requested_by: String(body.requested_by || OWNER).slice(0, 64),
  requested_at: now.toISOString()
}}];

const ctx = $('Подготовить контекст запуска').item.json;
const all = name => $(name).all()
  .flatMap(item => Array.isArray(item.json) ? item.json : [item.json])
  .filter(item => item && typeof item === 'object' && item.id && item.done !== true);
const compactFocus = (items, requestedId) => {
  const picked = requestedId ? items.filter(item => String(item.id) === requestedId) : items;
  return picked.slice(0, requestedId ? 1 : 5).map(item => ({
    id: String(item.id), case_id: String(item.case_id || ''),
    what: String(item.what || '').slice(0, 120)
  }));
};
const atlas = all('Открытые задачи Atlas');
const radar = all('Открытые задачи Radar');
const graph = all('Открытые задачи Graph');
const byCase = {case_66cae4a89ba6473f:'atlas', case_008f37d03cf541e5:'radar', case_43de12a8dc2e4abd:'graph'};
let focus = byCase[String(ctx.source_case_id || '').trim()] || '';
if (!focus) {
  const topic = String(ctx.requested_topic || '').toLowerCase();
  if (topic.includes('atlas')) focus = 'atlas';
  else if (topic.includes('radar')) focus = 'radar';
  else if (topic.includes('graph')) focus = 'graph';
}
if (!focus) focus = 'graph';
const requestedId = String(ctx.requested_source_action_id || '');
if (requestedId) {
  const reqFocus = byCase[String(ctx.source_case_id || '').trim()] || '';
  if (!reqFocus) throw new Error(`Собрать незакрытые задачи: requested_source_action_id ${requestedId} требует source_case_id одного из дел atlas/radar/graph`);
  focus = reqFocus;
  const focusList = focus === 'atlas' ? atlas : focus === 'radar' ? radar : graph;
  if (!focusList.some(item => String(item.id) === requestedId)) throw new Error(`Собрать незакрытые задачи: запрошенное действие ${requestedId} не найдено среди незакрытых действий дела ${focus} (закрыто или отсутствует); другое действие не выбирается`);
}
return [{json: {...ctx,
  focus,
  open_actions: {atlas: focus === 'atlas' ? compactFocus(atlas, requestedId) : [], radar: focus === 'radar' ? compactFocus(radar, requestedId) : [], graph: focus === 'graph' ? compactFocus(graph, requestedId) : []},
  open_counts: {atlas:atlas.length, radar:radar.length, graph:graph.length}
}}];

const ctx = $('Собрать незакрытые задачи').item.json;
const reply = String($json.reply || '');
const match = reply.match(/DISPATCH_JSON\s*([\s\S]*?)\s*END_DISPATCH_JSON/i) || reply.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
if (!match) throw new Error('Research Curator не вернул ограниченный DISPATCH_JSON');
let raw = match[1].trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let dispatch;
try { dispatch = JSON.parse(raw); } catch (error) { throw new Error(`DISPATCH_JSON не JSON: ${error.message}`); }
const fail = message => { throw new Error(`DISPATCH_JSON: ${message}`); };
if (!dispatch || typeof dispatch !== 'object' || Array.isArray(dispatch)) fail('нужен объект');
if (dispatch.schema_version !== '1.0' || dispatch.run_key !== ctx.run_key) fail('schema_version/run_key');
if (!['ready','waiting_human'].includes(dispatch.status)) fail('status');
if (typeof dispatch.needs_human !== 'boolean' || dispatch.needs_human !== (dispatch.status === 'waiting_human')) fail('needs_human/status');
if (!['atlas','radar','graph'].includes(dispatch.applies_to)) fail('applies_to');
const allowedTools = new Set(['sberindex_data_catalog','sberindex_query_data','sberindex_graph_kb_search','sberindex_directive_kb_search','sberindex_public_channel_record','jina_search_web','jina_read_url','apify_web_research','apify_web_research_results']);
if (!allowedTools.has(dispatch.tool_name)) fail('tool_name');
if (!dispatch.tool_args || typeof dispatch.tool_args !== 'object' || Array.isArray(dispatch.tool_args) || JSON.stringify(dispatch.tool_args).length > 2200) fail('tool_args');
const schemas = {
  sberindex_data_catalog: {allowed:['dataset'], required:[]},
  sberindex_query_data: {allowed:['dataset','columns','filters','limit'], required:['dataset']},
  sberindex_graph_kb_search: {allowed:['query','limit'], required:['query']},
  sberindex_directive_kb_search: {allowed:['query','limit'], required:['query']},
  sberindex_public_channel_record: {allowed:['label','platform','public_url','channel_kind','officiality','source_ref','checked_at','oktmo','latitude','longitude','geocode_precision','municipality_label','valid_from'], required:['label','platform','public_url','channel_kind','officiality','source_ref','checked_at','oktmo','latitude','longitude','geocode_precision','municipality_label']},
  jina_search_web: {allowed:['query','site'], required:['query']},
  jina_read_url: {allowed:['url'], required:['url']},
  apify_web_research: {allowed:['query','max_results','wait_seconds'], required:['query','wait_seconds']},
  apify_web_research_results: {allowed:['run_id','receipt','limit'], required:['run_id','receipt']}
};
const spec = schemas[dispatch.tool_name];
const argKeys = Object.keys(dispatch.tool_args);
if (argKeys.some(key => !spec.allowed.includes(key)) || spec.required.some(key => !(key in dispatch.tool_args))) fail('tool_args не соответствуют схеме инструмента');
if (['sberindex_graph_kb_search','sberindex_directive_kb_search','jina_search_web','apify_web_research'].includes(dispatch.tool_name) && (typeof dispatch.tool_args.query !== 'string' || dispatch.tool_args.query.trim().length < 2)) fail('tool_args.query');
if (dispatch.tool_name === 'jina_read_url' && (typeof dispatch.tool_args.url !== 'string' || !/^https:\/\//.test(dispatch.tool_args.url))) fail('tool_args.url');
if (dispatch.tool_name === 'sberindex_query_data' && typeof dispatch.tool_args.dataset !== 'string') fail('tool_args.dataset');
if (dispatch.tool_name === 'apify_web_research') {
  const apifyQuery = dispatch.tool_args.query.trim();
  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(apifyQuery) && !/^https:\/\//i.test(apifyQuery)) fail('Apify query: псевдосхемы вроде site: запрещены; нужен естественный текст или полный https URL');
  if (dispatch.tool_args.wait_seconds !== 0) fail('apify_web_research обязан быть асинхронным: wait_seconds=0');
  if ('max_results' in dispatch.tool_args && (!Number.isInteger(dispatch.tool_args.max_results) || dispatch.tool_args.max_results < 1 || dispatch.tool_args.max_results > 5)) fail('tool_args.max_results');
}
if (dispatch.tool_name === 'apify_web_research_results') {
  if (typeof dispatch.tool_args.run_id !== 'string' || !/^[A-Za-z0-9]{17}$/.test(dispatch.tool_args.run_id)) fail('tool_args.run_id [hint: run_id — это 17-значный id Apify-запуска из ответа apify_web_research (поле run_id), а НЕ run_key контура вида curator-YYYYMMDDHH; receipt — 64 hex-символа из того же ответа]');
  if (typeof dispatch.tool_args.receipt !== 'string' || !/^[A-Fa-f0-9]{64}$/.test(dispatch.tool_args.receipt)) fail('tool_args.receipt [hint: receipt — 64 hex-символа capability из ответа apify_web_research (поле receipt для ЭТОГО run_id и ЭТОГО плательщика); чек чужого запуска не подойдёт]');
}
if (typeof dispatch.plan_ref !== 'string' || !/^[ARG]\d{1,2}(?:[.-][A-Za-z0-9]+)?$/.test(dispatch.plan_ref)) fail('plan_ref');
const cases = {atlas:'case_66cae4a89ba6473f', radar:'case_008f37d03cf541e5', graph:'case_43de12a8dc2e4abd'};
if (dispatch.source_case_id !== cases[dispatch.applies_to]) fail('source_case_id не совпадает с applies_to');
const action = (ctx.open_actions[dispatch.applies_to] || []).find(item => item.id === dispatch.source_action_id);
if (!action) fail('source_action_id не найден среди незакрытых действий');
const requestedId = String(ctx.requested_source_action_id || '');
if (requestedId && dispatch.source_action_id !== requestedId) fail(`source_action_id ${dispatch.source_action_id} не совпадает с запрошенным ${requestedId}`);
if (requestedId && dispatch.applies_to !== ctx.focus) fail(`applies_to ${dispatch.applies_to} не совпадает с focus ${ctx.focus} запрошенного действия`);
for (const [field, min, max] of [['topic',5,500],['instruction',10,500],['reason',5,1000]]) {
  if (typeof dispatch[field] !== 'string' || dispatch[field].trim().length < min || dispatch[field].length > max) fail(field);
}
if (!dispatch.issued_at || Number.isNaN(Date.parse(dispatch.issued_at))) fail('issued_at');
dispatch.issued_at = new Date().toISOString();
if (dispatch.needs_human && (typeof dispatch.human_request !== 'string' || dispatch.human_request.trim().length < 5)) fail('human_request');
if (!dispatch.needs_human) dispatch.human_request = '';
const url = 'https://agrigate.pro/v2/#case/case_d058db85c48a487c';
const text = `# Задание Research Curator\n\nrun_key: ${ctx.run_key}\nstatus: ${dispatch.status}\nplan_ref: ${dispatch.plan_ref}\nsource_case_id: ${dispatch.source_case_id}\nsource_action_id: ${dispatch.source_action_id}\nissued_at: ${dispatch.issued_at}\n\n${JSON.stringify(dispatch, null, 2)}`;
return [{json: {...ctx, dispatch, title: `Curator dispatch ${ctx.run_key}: ${dispatch.plan_ref}`.slice(0,300), url, text, meta: {project:'sberindex-2026', kind:'research_curator_dispatch', curator_case_id:'case_d058db85c48a487c', run_key:ctx.run_key, status:dispatch.status, applies_to:dispatch.applies_to, plan_ref:dispatch.plan_ref, source_case_id:dispatch.source_case_id, source_action_id:dispatch.source_action_id, issued_at:dispatch.issued_at, schema_version:'1.0'}}}];

const base = $('Проверить DISPATCH_JSON').item.json;
const d = base.dispatch;
const state = $getWorkflowStaticData('global');
const key = `${d.source_action_id}:${d.human_request}`;
if (state.lastHumanRequestKey === key) return [];
state.lastHumanRequestKey = key;
const caseUrl = `https://agrigate.pro/v2/#case/${d.source_case_id}`;
const text = `🧭 СберИндекс: нужен Сергей

${d.plan_ref}: ${d.topic}

Что нужно: ${d.human_request}

Почему агент не может продолжить сам: ${d.reason}

Дело: ${caseUrl}
run_key: ${base.run_key}`.slice(0,3900);
return [{json:{chat_id:'30706370', text, run_key:base.run_key, notification_key:key}}];

const base = $('Проверить DISPATCH_JSON').item.json;
const d = base.dispatch;
const CASE_ID = 'case_43de12a8dc2e4abd';
const topic = d.topic.trim().slice(0, 500);
const args = JSON.stringify(d.tool_args);
const instruction = d.instruction.trim().slice(0, 500);
const channelSchema = /public_channel|t\.me|max\.ru/i.test(`${topic} ${d.instruction}`) ? ' Для Telegram/MAX entity_id public_channel:* ОБЯЗАТЕЛЬНО entity_type=public_channel и поля: platform=telegram|max, public_url, channel_kind=channel|chat, officiality=confirmed|candidate|unverified, source_ref HTTPS, checked_at ISO, oktmo 8 или 11 цифр, latitude, longitude, geocode_precision=building|street|settlement|municipality_centroid. Нельзя использовать entity_type=source, channel_kind=municipal_administration или geocode_precision=centroid_from_boundary. Все обязательные поля должны физически лежать внутри объекта entities[], а не только в claim или таблице GATE_REPORT. Если хотя бы одного поля нет в результате инструмента, не создавай сущность: status=blocked. Добавь связь OPERATED_BY, SERVES_TERRITORY либо LOCATED_IN.' : '';
const discoveryBoundary = /discovery-only|entities\s*=\s*\[\]/i.test(`${topic} ${instruction}`) ? ' Это discovery-only проход: entities ОБЯЗАН быть [], relations ОБЯЗАН быть []; кандидаты и ссылки перечисли только в claims. Не создавай вершину public_channel даже если поиск вернул канал.' : '';
const persistenceBoundary = d.tool_name === 'sberindex_public_channel_record' ? ' ВАЖНО: инструмент только детерминированно нормализует запись и ничего сам не сохраняет. Не утверждай, что инструмент уже записал сущность в corpus 77. Скажи, что валидная запись подготовлена; n8n выполнит ingest после проверки EVIDENCE_JSON.' : '';
const message = `Один атомарный проход по заданию Research Curator. run_key=${base.run_key}. plan_ref=${d.plan_ref}. source_case_id=${d.source_case_id}. source_action_id=${d.source_action_id}. Тема: ${topic}. Инструкция куратора: ${instruction}. Сделай РОВНО ОДИН настоящий native-вызов инструмента ${d.tool_name} с аргументами ${args}. Другие инструменты не вызывай. После фактического результата сразу верни EVIDENCE_JSON ... END_EVIDENCE_JSON schema_version 1.0 с полями run_key, topic, source_url, checked_at, status, entities, relations, claims, confidence и короткий GATE_REPORT. Не печатай псевдовызов. Для локального набора или корпуса используй source_url=https://agrigate.pro/v2/#case/case_43de12a8dc2e4abd и назови набор/корпус в claim. Для веба используй фактический HTTPS URL. Если инструмент не закрыл пробел или Apify ещё выполняется, status=blocked либо proposed и зафиксируй квитанцию/следующий машинный шаг. Не проси человека, пока доступен машинный путь. Не смешивай observed, source_estimate, model_estimate и synthetic_assumption.${channelSchema}${discoveryBoundary}${persistenceBoundary}`;
return [{json: {...base, case_id: CASE_ID, topic, message}}];

const ctx = $('Подготовить атомарный проход').item.json;
const reply = String($json.reply || '');
const match = reply.match(/EVIDENCE_JSON\s*([\s\S]*?)\s*END_EVIDENCE_JSON/i);
if (!match) throw new Error('Graph Steward не вернул ограниченный EVIDENCE_JSON');
let raw = match[1].trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let evidence;
try { evidence = JSON.parse(raw); } catch (error) { throw new Error(`EVIDENCE_JSON не JSON: ${error.message}`); }
const fail = message => { throw new Error(`EVIDENCE_JSON: ${message}`); };
const provenance = new Set(['observed','source_estimate','model_estimate','synthetic_assumption']);
if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) fail('нужен объект');
if (evidence.schema_version !== '1.0') fail('schema_version должен быть 1.0');
if (evidence.run_key !== ctx.run_key) fail('run_key не совпал с заданием');
if (String(evidence.topic || '').trim().length < 5) fail('topic пуст');
const https = value => typeof value === 'string' && /^https:\/\/[^\s]+$/i.test(value);
if (!https(evidence.source_url)) fail('source_url обязан быть https URL');
if (!evidence.checked_at || Number.isNaN(Date.parse(evidence.checked_at))) fail('checked_at обязан быть ISO-временем');
if (!['verified','proposed','blocked'].includes(evidence.status)) fail('неизвестный status');
if (typeof evidence.confidence !== 'number' || evidence.confidence < 0 || evidence.confidence > 1) fail('confidence вне 0..1');
for (const [name, max] of [['entities',100],['relations',200],['claims',100]]) {
  if (!Array.isArray(evidence[name]) || evidence[name].length > max) fail(`${name}: неверный тип или размер`);
}
const discoveryOnly = /discovery-only|entities\s*=\s*\[\]/i.test(`${ctx.topic || ''} ${ctx.dispatch?.instruction || ''}`);
if (discoveryOnly && (evidence.entities.length || evidence.relations.length)) fail('discovery-only требует entities=[] и relations=[]');
const ids = new Set();
const channelIds = new Set();
const linkedChannelIds = new Set();
for (const entity of evidence.entities) {
  if (!entity || typeof entity.entity_id !== 'string' || entity.entity_id.length < 3 || ids.has(entity.entity_id)) fail('entity_id пуст или повторён');
  if (!['municipality','organization','public_channel','dataset','indicator','event','source','synthetic_actor'].includes(entity.entity_type)) fail(`entity_type ${entity.entity_type}`);
  const channelLike = entity.entity_id.startsWith('public_channel:') || (typeof entity.source_ref === 'string' && /^https:\/\/(?:t\.me|telegram\.me|max\.ru)\//i.test(entity.source_ref));
  if (channelLike && entity.entity_type !== 'public_channel') fail('Telegram/MAX площадка обязана иметь entity_type public_channel');
  if (!provenance.has(entity.provenance_class)) fail('неверный provenance сущности');
  if (entity.provenance_class === 'synthetic_assumption' && entity.entity_type !== 'synthetic_actor') fail('синтетическая сущность обязана иметь тип synthetic_actor');
  if (entity.entity_type === 'public_channel') {
    if (!['telegram','max'].includes(entity.platform)) fail('public_channel platform');
    if (typeof entity.public_url !== 'string' || !/^https:\/\/(?:t\.me|telegram\.me|max\.ru)\/[^\s/?#]+\/?$/i.test(entity.public_url)) fail('public_channel public_url');
    if (!['channel','chat'].includes(entity.channel_kind)) fail('public_channel channel_kind');
    if (!['confirmed','candidate','unverified'].includes(entity.officiality)) fail('public_channel officiality');
    if (!https(entity.source_ref) || !entity.checked_at || Number.isNaN(Date.parse(entity.checked_at))) fail('public_channel source_ref/checked_at');
    if (typeof entity.oktmo !== 'string' || !/^[0-9]{8}(?:[0-9]{3})?$/.test(entity.oktmo)) fail('public_channel oktmo');
    if (typeof entity.latitude !== 'number' || entity.latitude < -90 || entity.latitude > 90 || typeof entity.longitude !== 'number' || entity.longitude < -180 || entity.longitude > 180) fail('public_channel coordinates');
    if (!['building','street','settlement','municipality_centroid'].includes(entity.geocode_precision)) fail('public_channel geocode_precision');
    channelIds.add(entity.entity_id);
  }
  ids.add(entity.entity_id);
}
for (const relation of evidence.relations) {
  if (!ids.has(relation.source_entity_id) || !ids.has(relation.target_entity_id)) fail('relation ссылается на неизвестную сущность');
  if (!provenance.has(relation.provenance_class) || !https(relation.evidence_url)) fail('relation без provenance/https evidence');
  if (typeof relation.confidence !== 'number' || relation.confidence < 0 || relation.confidence > 1) fail('relation confidence вне 0..1');
  const channelId = channelIds.has(relation.source_entity_id) ? relation.source_entity_id : (channelIds.has(relation.target_entity_id) ? relation.target_entity_id : '');
  if (channelId) {
    if (!['OPERATED_BY','SERVES_TERRITORY','LOCATED_IN'].includes(relation.relation_type)) fail('public_channel relation_type');
    linkedChannelIds.add(channelId);
  }
}
for (const channelId of channelIds) if (!linkedChannelIds.has(channelId)) fail('public_channel обязан быть связан с municipality или organization');
for (const claim of evidence.claims) {
  if (typeof claim.statement !== 'string' || claim.statement.trim().length < 3) fail('claim без statement');
  if (!provenance.has(claim.provenance_class) || !https(claim.evidence_url)) fail('claim без provenance/https evidence');
  if (typeof claim.confidence !== 'number' || claim.confidence < 0 || claim.confidence > 1) fail('claim confidence вне 0..1');
}
if (ctx.dispatch && ctx.dispatch.tool_name === 'sberindex_public_channel_record' && evidence.claims.some(claim => /инструмент.+(?:записал|сохранил).+(?:corpus|корпус|staging)/i.test(String(claim.statement || '')))) fail('sberindex_public_channel_record нормализует, но не записывает; ingest выполняет n8n после этой проверки');
if (evidence.status === 'verified' && evidence.claims.length === 0) fail('verified требует хотя бы один claim');
const text = `# Муниципальный граф — staging evidence\n\nrun_key: ${ctx.run_key}\ntrigger: ${ctx.trigger}\nstatus: ${evidence.status}\nchecked_at: ${evidence.checked_at}\nsource: ${evidence.source_url}\n\n${JSON.stringify(evidence, null, 2)}`;
return [{json: {title: `Graph evidence ${ctx.run_key}: ${ctx.topic}`.slice(0, 300), url: evidence.source_url, text, meta: {project: 'sberindex-2026', kind: 'municipality_graph_evidence', case_id: ctx.case_id, run_key: ctx.run_key, topic: ctx.topic, trigger: ctx.trigger, status: evidence.status, checked_at: evidence.checked_at, schema_version: '1.0'}, evidence}}];

